//! Inner Sea Races shared spell list.
//!
//! Generated by `src/bin/ingest_spells.rs` (config-driven, all
//! books) from the real `pathfinder/paizo/campaign_setting/inner_sea_races/isr_spells.lst` corpus. Record coverage: every
//! real, active (non-`.MOD`, non-`.COPY=`) base spell declaration.
//!
//! `level` is the minimum level across the record's `CLASSES:`/
//! `DOMAINS:` token(s), `None` for the rare record that states
//! neither (never fabricated -- these land `text-complete`, not
//! `ingested-magnitude`, via `v06_work_inventory::classify`'s
//! existing `Some(false)` branch).
//!
//! `school`/`description` are `Option` because a minority of
//! records carry neither token of their own on this book's base
//! row.

/// The full 9-school PF1 spell-school enum, mirroring every other book's
/// own copy exactly.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Pf1SchoolId {
    Abjuration,
    Conjuration,
    Divination,
    Enchantment,
    Evocation,
    Illusion,
    Necromancy,
    Transmutation,
    Universal,
}

impl Pf1SchoolId {
    pub fn from_corpus_str(raw: &str) -> Option<Self> {
        match raw {
            "Abjuration" => Some(Pf1SchoolId::Abjuration),
            "Conjuration" => Some(Pf1SchoolId::Conjuration),
            "Divination" => Some(Pf1SchoolId::Divination),
            "Enchantment" => Some(Pf1SchoolId::Enchantment),
            "Evocation" => Some(Pf1SchoolId::Evocation),
            "Illusion" => Some(Pf1SchoolId::Illusion),
            "Necromancy" => Some(Pf1SchoolId::Necromancy),
            "Transmutation" => Some(Pf1SchoolId::Transmutation),
            "Universal" => Some(Pf1SchoolId::Universal),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SpellListEntry {
    pub key: &'static str,
    /// `decisions.md §24`: `Some(line)` ONLY when `key` above
    /// is a Codex-generated neutral identity (the row's real
    /// name is Product Identity) -- carries the real citation
    /// line so `cache_gen::spell_lane_dump` can resolve it
    /// without a name-based lookup. `None` for an ordinary entry.
    pub name_pi_line: Option<u32>,
    pub school: Option<Pf1SchoolId>,
    pub level: Option<u8>,
    pub description: Option<&'static str>,
}

pub const SPELL_LIST: &[SpellListEntry] = &[
    SpellListEntry { key: "Air of Authority", name_pi_line: None, school: Some(Pf1SchoolId::Illusion), level: Some(3), description: Some("You gain an unmistakable air of authority, which clouds creatures' minds and causes them to believe that you are their direct superior. Each creature with whom you attempt to leverage your newfound authority receives a Will save to disbelieve the illusion. Otherwise, it treats you as it would its direct superior. Creatures with different direct superiors see you in different ways, which can potentially lead to conflicts that allow additional saving throws (for instance, if a cook sees you as the head chef, he might be quite perplexed to see the vizier treating you as if you were the king).") },
    SpellListEntry { key: "Bleaching Resistance", name_pi_line: None, school: Some(Pf1SchoolId::Enchantment), level: Some(4), description: Some("Ability score drain from the Bleaching doesn't affect your ability score modifiers while you're affected by this spell. This spell does not remove the Bleaching's effect on your appearance, nor does it prevent you from suffering further ability penalties, dying, or becoming a bleachling as a result of the Bleaching.") },
    SpellListEntry { key: "Burn Corruption", name_pi_line: None, school: Some(Pf1SchoolId::Evocation), level: Some(4), description: Some("This spell fills the area with violet flames that scour an area clean of life-especially of the corrupted life of the Abyss. Creatures (and foliage) in the area take %1d8 points of fire damage unless they are outsiders with the chaotic and evil subtypes or are otherwise tainted by demons, in which case they instead take %2d6 points of fire damage. This fire damage ignores the fire resistance granted by the demon subtype, but it does not penetrate any other form of fire resistance or immunity.") },
    SpellListEntry { key: "Carve Passage", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(5), description: Some("You can excavate and move an amount of snow, earth, dust, sand, and loose or packed rocks or ice chunks (each no more than 5 feet in diameter) whose volume fills %1 five-foot cubes. If you are buried, you can open a space around yourself and use any remaining cubes for tunneling. This spell is otherwise similar to expeditious excavation. Carve passage has no effect on earth creatures or solid rock or ice.") },
    SpellListEntry { key: "Champion's Bout", name_pi_line: None, school: Some(Pf1SchoolId::Enchantment), level: Some(3), description: Some("You allow two chosen champions to fight without interference. The two creatures must be willing in order for the spell to work. After you cast this spell, any creature attempting to aid or hinder either of the two targets in any way must succeed at a Will save or lose its action instead (spell resistance applies). A creature that fails its Will save against champion's bout cannot attempt to interfere again. If a creature successfully interferes with the bout, the spell ends immediately.") },
    SpellListEntry { key: "Damnation of Memory", name_pi_line: None, school: Some(Pf1SchoolId::Enchantment), level: Some(6), description: Some("You name one creature and excise all memory of that creature's involvement in events the targets remember. The targets either forget who exactly performed the named creature's deeds or assume some other individual performed them. Alternatively, you can name either one event lasting no more than %1 minutes or a single topic (defined at the GM's discretion) such as a shameful secret of the king that was recently revealed or a small revolt that was quelled messily, and erase all recollection of that subject from the minds of all creatures within the area. Memory of facts and topics that are common knowledge (information with a Knowledge check DC of 10 or less) cannot be stolen via this spell.") },
    SpellListEntry { key: "Elemental Mastery", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(4), description: Some("You gain mastery over the element matching the elemental essence in your blood. Your mastery gives you a +20 ft. insight bonus to the speed of all your movement modes, and a +1 circumstance bonus on attack rolls when your foe is on fire.") },
    SpellListEntry { key: "Elemental Mastery", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(4), description: Some("You gain mastery over the element matching the elemental essence in your blood. Your mastery gives you a burrow speed of 15 ft., and a +1 circumstance bonus on attack rolls when both you and your foe are touching the ground.") },
    SpellListEntry { key: "Elemental Mastery", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(4), description: Some("You gain mastery over the element matching the elemental essence in your blood. You can choose any one of the four elements as you cast this spell. Your mastery gives you an insight bonus to your speed or a new movement mode, depending on the element you choose, and grants one additional benefit. This spell's descriptor matches the chosen element. Air; Fly 30 ft. (average), +1 circumstance bonus on attack rolls when both you and your foe are airborne. Earth; Burrow 15 ft., +1 circumstance bonus on attack rolls when both you and your foe are touching the ground. Fire; +20 ft. on all speeds, +1 circumstance bonus on attack rolls when your foe is on fire. Water;  +30 ft. swim, +1 circumstance bonus on attack rolls when both you and your foe are touching water.") },
    SpellListEntry { key: "Elemental Mastery", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(4), description: Some("You gain mastery over the element matching the elemental essence in your blood. Your mastery gives you a fly speed of 30 ft. (average maneuverablity), and a +1 circumstance bonus on attack rolls when both you and your foe are airborne.") },
    SpellListEntry { key: "Elemental Mastery", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(4), description: Some("You gain mastery over the element matching the elemental essence in your blood. Your mastery gives you a +30 ft. insight bonus to your movement swim speed, and a +1 circumstance bonus on attack rolls when both you and your foe are touching water.") },
    SpellListEntry { key: "Fable Tapestry", name_pi_line: None, school: Some(Pf1SchoolId::Illusion), level: Some(4), description: Some("[redacted PI]") },
    SpellListEntry { key: "Fire's Friend", name_pi_line: None, school: Some(Pf1SchoolId::Evocation), level: Some(2), description: Some("You cloak yourself in flames that do not harm you or your carried equipment but damage other creatures and objects. The flames cast light as a torch. Any creature that attacks you with a non-reach melee weapon or that begins its turn engaged in a grapple with you takes 1d6 points of fire damage and must succeed at a Reflex save or catch fire. The creature can negate the damage (and avoid catching fire) with spell resistance. Any time you end your movement in the same square as a flammable object or creature, that creature or object must succeed at a Reflex save or catch fire.") },
    SpellListEntry { key: "Fleshwarping Swarm", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(3), description: Some("This spell functions as summon swarm, except that living and undead creatures that fail their saving throw against the swarm's distraction find that their limbs twist and spasm, as their bodies become susceptible to transmutations. Such creatures take a -4 penalty to Dexterity and on saving throws against transmutation effects for %1 hours.") },
    SpellListEntry { key: "Lament of Summer's Last Breath", name_pi_line: None, school: Some(Pf1SchoolId::Abjuration), level: Some(2), description: Some("You wrap the target in a mantle of summery air, within which the ambient temperature never falls below 70 degrees Fahrenheit. Creatures with the cold subtype that start their turns in the area take 1d4 + %1 points of fire damage no saving throw. Each time an evil dragon, fey, or giant takes damage from the spell, it must succeed at a Will saving throw or become shaken for 1 round. Creatures attempting to cast a cold spell in the area must succeed at a Will save or the spell fails. Succeeding at one such save to cast a spell allows a creature to continue casting cold spells in the area for the spell's remainder.") },
    SpellListEntry { key: "Lost Locale", name_pi_line: None, school: Some(Pf1SchoolId::Enchantment), level: Some(9), description: Some("Creatures in the area of this spell are subject to a subtle enchantment that confounds their senses of direction, interferes with recognizing landmarks, and causes them to misjudge distances and angles. Creatures that enter the area must succeed at a new Survival check to avoid becoming lost immediately, whether or not they succeed at their saving throws. Those that fail the save take a -%1 penalty on such Survival checks, treat all squares they enter as difficult terrain for as long as they are in the area and for %2 hours thereafter, lose the benefit of all effects that allow them to ignore difficult terrain, and take a -4 penalty to Dexterity.") },
    SpellListEntry { key: "Lost Passage", name_pi_line: None, school: Some(Pf1SchoolId::Enchantment), level: Some(3), description: Some("Creatures in the area of this spell are subject to a subtle enchantment that confounds their senses of direction, interferes with recognizing landmarks, and causes them to misjudge distances and angles. Creatures that enter the area must succeed at a new Survival check to avoid becoming lost immediately, whether or not they succeed at their saving throws. Those that fail the save take a -%1 penalty on such Survival checks, treat all squares they enter as difficult terrain for as long as they are in the area and for %2 hours thereafter, lose the benefit of all effects that allow them to ignore difficult terrain, and take a -4 penalty to Dexterity.") },
    SpellListEntry { key: "Mantle of the Magic Warriors", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(5), description: Some("You weave golden masks shaped like animals around the targets' faces, imbuing each target with an animal spirit that matches her strength of character. Each target gains one animal special ability of your choice granted by beast shape I. You can choose a different special ability for each target.") },
    SpellListEntry { key: "Martial Telekinesis", name_pi_line: None, school: Some(Pf1SchoolId::Evocation), level: Some(3), description: Some("Once per round, you can use telekinesis to perform a bull rush, disarm, grapple (including pin), or trip. Resolve these attempts as normal, except that they don't provoke attacks of opportunity, you use your caster level in place of your Combat Maneuver Bonus, and you add your Intelligence modifier (if a wizard) or Charisma modifier (if a sorcerer) in place of your Strength or Dexterity modifier. No save is allowed against these attempts, but spell resistance applies normally. This version of the spell can last 1 round per caster level, but it ends if you cease concentration. Alternatively, you can inflict a telekinetic unarmed strike with this spell, using your own unarmed strike damage and applying your primary spellcasting ability score modifier to the damage in place of your Strength modifier.") },
    SpellListEntry { key: "Miasmal Dread", name_pi_line: None, school: Some(Pf1SchoolId::Enchantment), level: Some(2), description: Some("A cloud of sickly green mist pours from your mouth and coalesces around creatures in the cone. Attempt a single Intimidate check to demoralize as part of casting the spell, comparing the result against the DC to Intimidate each foe within the area. You demoralize all foes whose DC you meet or exceed.") },
    SpellListEntry { key: "Murderous Crow", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(1), description: Some("You conjure a supernaturally vicious and clever crow to watch over you on the battlefield. Choose one of the following templates; the crow has that template and this spell gains the descriptor listed in parentheses: celestial (good), entropic (chaotic), fiendish (evil), or resolute (lawful). In addition to its normal abilities, the crow gains the Improved Steal feat as a bonus feat and gains an eye rake attack. If both of its claw attacks hit the same living foe in a single round, that foe must succeed at a DC 13 Reflex save or be blinded as the bird scratches and tears at the foe's eyes. The blindness lasts for 1d4 days or until healed with remove blindness. If the focus leaves your possession, the crow vanishes and the spell ends.") },
    SpellListEntry { key: "Overlook", name_pi_line: None, school: Some(Pf1SchoolId::Enchantment), level: Some(3), description: Some("You enhance your natural ability to seem small and unimportant, causing those around you to overlook you. You gain a +20 bonus on Stealth checks, which doesn't stack with bonuses from effects that actually make you sneakier, such as invisibility or respectful quiet; you do not need cover or concealment to hide; and you can hide while you are being observed. If a creature fails to notice you because of this spell, that creature can still remember seeing a halfling pass by, but attach no importance to the memory. You do not gain these benefits against creatures that are immune to compulsions or mind-affecting effects, and spell resistance applies. If you take an actively aggressive or extremely conspicuous action, creatures automatically notice you, and you gain no further benefits against those creatures for the remainder of the spell's duration.") },
    SpellListEntry { key: "Probe History", name_pi_line: None, school: Some(Pf1SchoolId::Divination), level: Some(2), description: Some("If the target fails her Will save, you can ask about one topic and attempt the appropriate Knowledge check with a +5 competence bonus; track Knowledge checks attempted with this spell separately for the purpose of disallowing retries on Knowledge checks. Once you have probed a target's history, successfully or not, you cannot target the same creature's history or search for the same information in another creature's history.") },
    SpellListEntry { key: "Respectful Quiet", name_pi_line: None, school: Some(Pf1SchoolId::Illusion), level: Some(3), description: Some("All targets are rendered silent, as per silence. The silence affects the entirety of each creature but does not extend beyond. However, the silence is one-way-sounds from outside the creatures' spaces can still enter. Quieted creatures gain a +10 circumstance bonus on Stealth checks.") },
    SpellListEntry { key: "Shadow of Doubt", name_pi_line: None, school: Some(Pf1SchoolId::Enchantment), level: Some(4), description: Some("You create a shadowy aura of doubt fueled by a foe's own inner flaws. Targets perceive all illumination as if it were one light level darker, to a minimum light level of darkness (not supernatural darkness), even on a successful saving throw. Fleeting mental shadows of regrets and anxieties distract the spell's targets; at the start of each of their turns, they must each succeed at a Will save or be staggered for 1 round. A good-aligned target takes a -4 penalty on saving throws against this effect; an evil-aligned target gains a +4 bonus instead.") },
    SpellListEntry { key: "Siege Scatter", name_pi_line: None, school: Some(Pf1SchoolId::Evocation), level: Some(4), description: Some("A roiling blast of rough rock and dirt scatters along the ground in the area, dealing %1d6 points of slashing damage to all creatures on the ground in the area, even on a successful saving throw. Creatures in the area that fail the Reflex save fall prone and are knocked to the nearest edge of the area, taking 1d6 points of bludgeoning damage for every 10 feet they travel this way. Creatures that did not move during the past round and those with the stability racial trait gain a +4 bonus on the saving throw.") },
    SpellListEntry { key: "Summon Giant Ally I", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(6), description: Some("This spell functions as summon nature's ally VI, except its casting time is shorter and you can summon one cave, hill, marsh, river, slag, stone, or wood giant.") },
    SpellListEntry { key: "Summon Giant Ally II", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(7), description: Some("This spell functions as summon giant ally I, except you can summon one desert, fire, frost, or jungle giant or 1d3 cave, hill, marsh, river, slag, stone, or wood giants.") },
    SpellListEntry { key: "Summon Giant Ally III", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(8), description: Some("This spell functions as summon giant ally I, except you can summon one ash or cloud giant; 1d3 desert, fire, frost, or jungle giants; or 1d4+1 cave, hill, marsh, river, slag, stone, or wood giants.") },
    SpellListEntry { key: "Summon Kami", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(5), description: Some("This spell functions as summon nature's ally V, except you can summon one kodama, 1d3 fukujin, or 1d4+1 shikigami.") },
    SpellListEntry { key: "Suppressing Stone", name_pi_line: None, school: Some(Pf1SchoolId::Evocation), level: Some(3), description: Some("You infuse arcane power into the focus ioun stone, which must be currently floating around your head. If the ioun stone ever ceases floating around you, the spell ends immediately, and the spell fails if the ioun stone in question is cracked, burned, flawed, or otherwise of lesser value. While the spell is active, you gain a +%1 resistance bonus on saving throws against mind-affecting effects. Whenever you fail a saving throw against a mind-affecting spell or effect, you can burn out the focus, transforming it irrevocably into a dull gray ioun stone and ending this spell, but suppressing the mind-affecting effect for 1 round per 2,500 gp of value of the focus (minimum 1 round). Rounds during which the effect is suppressed still count against its duration, and the effect can still be dispelled or disrupted during this time.") },
    SpellListEntry { key: "Wall of Brine", name_pi_line: None, school: Some(Pf1SchoolId::Evocation), level: Some(3), description: Some("You conjure a 5-foot-thick wall of seawater with a powerful current flowing toward one side of the wall, selected by you; a creature attempting to swim against this current must spend 4 squares of movement to enter a square of the wall. A creature that begins its turn in the wall is ejected in the direction of the current just before it acts. The wall provides cover against attacks from out of the water, as usual for a body of water. The water and the currents deflect physical ranged attacks into or through the wall, unless a weapon used is exceptionally massive (such as a siege engine). A creature submerged in the wall takes the usual penalties for underwater combat. The wall blocks gases and liquids and prevents water from mixing at its edges.") },
    SpellListEntry { key: "Zephyr's Fleetness", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(3), description: Some("You can call upon the spirits of the air to grant agility to your allies. Each target gains a +30 foot enhancement bonus to its land speed and fly speed (if any). Each target can also move (and charge) through difficult terrain without penalty.") },
];
